<?php
declare(strict_types=1);require_once __DIR__.'/../business/config/public_store_step23.php';require_once __DIR__.'/pwa_step24.php';$error=null;$catalog=[];$settings=[];try{$pdo=ps23_db();ps23_ensure($pdo);$ctx=ps23_context($pdo);$settings=ps23_settings($pdo,$ctx['organization_id']);foreach(ps23_catalog($pdo,$ctx['organization_id']) as $row)$catalog[(int)$row['id']]=['id'=>(int)$row['id'],'name'=>$row['product_name'],'sku'=>$row['sku'],'mrp'=>(float)$row['mrp'],'vp'=>(float)$row['volume_points'],'category'=>strtoupper((string)$row['category_name']),'availability'=>$row['availability_status']];}catch(Throwable $e){$error=$e->getMessage();}$catalogJson=json_encode($catalog,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);?><!doctype html><html lang="en-IN"><head><?php s24_head('Checkout Request - Healthcare Wellness Club','Submit your product cart to Healthcare Wellness Club for final review and confirmation.','checkout.php','noindex,nofollow,noarchive');?></head><body><a class="skip-link" href="#main-content">Skip to main content</a><header class="store-top"><div class="store-bar"><a class="store-brand" href="index.php"><img src="../img/logo.png" alt="Healthcare Wellness Club" width="42" height="42"><span><strong>Healthcare Wellness Club</strong><small>Order Request Checkout</small></span></a><nav class="store-actions" aria-label="Checkout actions"><a class="store-btn" href="cart.php">Back to Cart</a><a class="store-btn primary" href="index.php">Products</a></nav></div></header><main class="store-shell" id="main-content"><section class="store-hero" aria-labelledby="checkout-title"><div class="store-kicker">SECURE ORDER REQUEST</div><h1 id="checkout-title">Send your cart to the club for final confirmation.</h1><p>This is not an instant paid checkout. Current MRP/VP is recalculated by the server; the club confirms availability, any eligible pricing, taxes, delivery and payment separately.</p></section><?php if($error):?><div class="notice bad" role="alert"><?=ps23_h($error)?></div><?php endif;?><section class="two-col" style="margin-top:16px"><article class="card"><h2>Your details</h2><form id="checkoutForm" method="post" action="submit.php"><input type="hidden" name="cart_json" id="cart_json"><input type="hidden" name="started_at" id="started_at"><div class="hp-field" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="checkout-grid"><label for="customerName">Name<input class="store-input" id="customerName" name="name" maxlength="190" autocomplete="name" required></label><label for="customerMobile">Mobile<input class="store-input" id="customerMobile" name="mobile" maxlength="40" inputmode="tel" autocomplete="tel" required></label><label class="full" for="customerEmail">Email (optional)<input class="store-input" id="customerEmail" type="email" name="email" maxlength="190" inputmode="email" autocomplete="email"></label><label for="delivery_mode">Delivery mode<select class="store-select" name="delivery_mode" id="delivery_mode"><option value="club_pickup">Club Pickup</option><option value="home_delivery">Home Delivery / Ecom Drop Point</option></select></label><label for="postalCode">Postal code (optional)<input class="store-input" id="postalCode" name="postal_code" maxlength="20" inputmode="numeric" autocomplete="postal-code"></label><label class="full" id="addressLabel" for="address" hidden>Delivery address<textarea class="store-textarea" name="address" id="address" rows="3" maxlength="1500" autocomplete="street-address"></textarea></label><label class="full" for="orderNote">Note (optional)<textarea class="store-textarea" id="orderNote" name="note" rows="3" maxlength="2000" placeholder="Product/order note only. Do not send private medical records."></textarea></label><label class="full consent-row" for="consent"><input type="checkbox" id="consent" name="consent" value="1" required><span>I agree that Healthcare Wellness Club may contact me about this product order request.</span></label></div><div id="formAlert" role="status" aria-live="polite" aria-atomic="true"></div><button class="store-btn primary" id="submitBtn" type="submit" style="width:100%;margin-top:12px">Send Order Request</button></form></article><aside class="card"><h2>Server-verified preview</h2><div id="checkoutItems" aria-live="polite"></div><div class="summary-line"><span>MRP Total</span><strong id="mrp">₹0.00</strong></div><div class="summary-line"><span>Total VP</span><strong id="vp">0</strong></div><div class="summary-line"><span>Delivery</span><strong id="delivery">₹0.00</strong></div><div class="summary-line grand"><span>Estimated Total</span><strong id="grand">₹0.00</strong></div><div class="notice warn">₹100 delivery charge excluding taxes is shown for applicable nutrition delivery requests below 100 VP. Tax is not calculated in this portal.</div><div class="notice">Payment mode: <b><?=ps23_h(strtoupper((string)($settings['payment_mode']??'review_only')))?></b>. No online payment is collected now.</div></aside></section></main><footer class="store-footer">Your request becomes a final sale only after Business OS review. <span class="network-badge" data-network-status role="status" aria-live="polite">Online</span></footer><script src="<?=s24_h(s24_asset('store.js'))?>" defer></script><script>
document.addEventListener('DOMContentLoaded',()=>{const catalog=<?=$catalogJson?:'{}'?>;const form=document.getElementById('checkoutForm');const mode=document.getElementById('delivery_mode');const money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(value);const esc=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));function preview(){const cart=hwcCart();document.getElementById('cart_json').value=JSON.stringify(cart);let mrp=0,vp=0,hasNutrition=false;const box=document.getElementById('checkoutItems');box.innerHTML='';for(const row of cart){const product=catalog[Number(row.product_id)];if(!product)continue;const qty=Math.max(1,Math.min(20,Number(row.qty)||1));mrp+=product.mrp*qty;vp+=product.vp*qty;if(!['ART OF PROMOTION','APPLICATIONS'].includes(product.category))hasNutrition=true;const div=document.createElement('div');div.className='summary-line';div.innerHTML=`<span>${qty} × ${esc(product.name)}</span><strong>${money(product.mrp*qty)}</strong>`;box.appendChild(div)}const delivery=mode.value==='home_delivery'&&hasNutrition&&vp>0&&vp<100?100:0;document.getElementById('mrp').textContent=money(mrp);document.getElementById('vp').textContent=vp.toFixed(3).replace(/0+$/,'').replace(/\.$/,'');document.getElementById('delivery').textContent=money(delivery);document.getElementById('grand').textContent=money(mrp+delivery);const addressLabel=document.getElementById('addressLabel');const address=document.getElementById('address');const needsAddress=mode.value==='home_delivery';addressLabel.hidden=!needsAddress;address.required=needsAddress;return cart.length>0}mode.addEventListener('change',preview);document.getElementById('started_at').value=String(Date.now());preview();form.addEventListener('submit',async event=>{event.preventDefault();const alertBox=document.getElementById('formAlert');if(!navigator.onLine){alertBox.innerHTML='<div class="notice bad">Internet connection is required to submit an order request.</div>';return}if(!preview()){alertBox.innerHTML='<div class="notice bad">Your cart is empty.</div>';return}if(!form.reportValidity())return;const button=document.getElementById('submitBtn');button.disabled=true;button.textContent='Submitting…';try{const response=await fetch('submit.php',{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.message||'Order request could not be submitted.');if(!data.order_code||!data.status_token){alertBox.innerHTML='<div class="notice">Thanks. Your request has been received.</div>';hwcClear();return}hwcClear();const statusForm=document.createElement('form');statusForm.method='post';statusForm.action='status.php';for(const [key,value] of Object.entries({code:data.order_code,token:data.status_token,created:'1'})){const input=document.createElement('input');input.type='hidden';input.name=key;input.value=value;statusForm.appendChild(input)}document.body.appendChild(statusForm);statusForm.submit()}catch(error){alertBox.innerHTML='<div class="notice bad">'+esc(error.message||'Something went wrong.')+'</div>'}finally{button.disabled=false;button.textContent='Send Order Request'}})});
</script></body></html>
